<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Plus, ArrowDownToLine, Package, ClipboardList } from '@lucide/vue'
import { api, list, money, today } from '../api'
import type { Ingredient, Movement } from '../types'
import AppModal from '../components/AppModal.vue'
const ingredients=ref<Ingredient[]>([]), movements=ref<Movement[]>([]), modal=ref(''), error=ref(''), formError=ref(''), busy=ref(false), key=ref(crypto.randomUUID()), pending=ref<{path:string;body:string}>()
const form=reactive({ingredient:0,quantity:'',note:'',kind:'consumption',date:today()}), item=reactive({name:'',unit:'kg',minimum:'0'})
const low=computed(()=>ingredients.value.filter(i=>Number(i.quantity)<=Number(i.minimum)).length)
async function load(){try{[ingredients.value,movements.value]=await Promise.all([list<Ingredient>('ingredients/'),api<Movement[]>('stock/')])}catch(e){error.value=(e as Error).message}}
onMounted(load)
function start(kind:string){formError.value='';modal.value=kind;if(pending.value)return;key.value=crypto.randomUUID();Object.assign(form,{ingredient:ingredients.value[0]?.id||0,quantity:'',note:kind==='consumption'?'Kunlik haqiqiy sarf':'',kind,date:today()});Object.assign(item,{name:'',unit:'kg',minimum:'0'})}
async function save(){busy.value=true;formError.value='';try{const path=modal.value==='item'?'ingredients/':'stock/'; if(!pending.value)pending.value={path,body:JSON.stringify(modal.value==='item'?item:{...form,key:key.value})};await api(pending.value.path,{method:'POST',body:pending.value.body});pending.value=undefined;modal.value='';await load()}catch(e){formError.value=(e as Error).message;if((e as {status?:number}).status===400)pending.value=undefined}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">MAHSULOTLAR NAZORATI</span><h1>Ombor va sarf<span class="heading-dot">.</span></h1><p>Retseptli taom sotilganda xomashyo avtomatik ayriladi.</p></div><div class="heading-actions"><button class="button secondary" :disabled="!!pending" @click="start('item')"><Plus :size="17"/>Mahsulot</button><button class="button secondary" :disabled="!!pending||!ingredients.length" @click="start('receipt')"><ArrowDownToLine :size="17"/>Kirim</button><button class="button primary" :disabled="!ingredients.length" @click="start(pending?'consumption':'consumption')"><ClipboardList :size="17"/>{{ pending?'Amalni tekshirish':'Sarf kiritish' }}</button></div></div><p v-if="error" class="alert error">{{ error }}</p><div class="inventory-summary"><div><Package :size="21"/><span><strong>{{ ingredients.length }}</strong> xil mahsulot</span></div><div><span class="warning-dot"/><span><strong>{{ low }}</strong> ta kam qolgan</span></div><p>Retsept bog‘langan taom to‘langanda masalliqlar avtomatik ayriladi. Qolgan haqiqiy sarfni alohida kiriting.</p></div><section class="panel"><header class="panel-heading"><div><h2>Xomashyo qoldig‘i</h2><p>Registrdagi miqdor · sotuv va sarf harakatlari bilan yangilanadi</p></div><span class="pill subtle">Asosiy ombor</span></header><div class="table-wrap"><table><thead><tr><th>MAHSULOT</th><th>QOLDIQ</th><th>MINIMAL ME’YOR</th><th>HOLAT</th></tr></thead><tbody><tr v-for="row in ingredients" :key="row.id"><td><strong>{{ row.name }}</strong></td><td class="number">{{ money(row.quantity) }} {{ row.unit }}</td><td>{{ money(row.minimum) }} {{ row.unit }}</td><td><span class="status" :class="Number(row.quantity)<=Number(row.minimum)?'open':'paid'">{{ Number(row.quantity)<=Number(row.minimum)?'Kam qolgan':'Yetarli' }}</span></td></tr></tbody></table><div v-if="!ingredients.length" class="empty-state">Xomashyo ro‘yxatiga mahsulot qo‘shing.</div></div></section><section class="panel spaced"><header class="panel-heading"><div><h2>Ombor harakatlari</h2><p>So‘nggi 100 ta kirim, sarf va sotuv bo‘yicha yozuv</p></div></header><div class="table-wrap"><table><thead><tr><th>MAHSULOT</th><th>AMAL</th><th>MIQDOR</th><th>SANA</th><th>IZOH</th></tr></thead><tbody><tr v-for="row in movements" :key="row.id"><td>{{ row.ingredient_name }}</td><td><span class="status" :class="row.kind==='receipt'?'paid':'open'">{{ row.kind==='receipt'?'Kirim':row.kind==='sale_consumption'?'Sotuv sarfi':'Sarf' }}</span></td><td class="number">{{ row.kind==='receipt'?'+':'−' }}{{ money(row.quantity) }} {{ row.unit }}</td><td>{{ row.date }}</td><td>{{ row.note }}</td></tr></tbody></table><div v-if="!movements.length" class="empty-state compact">Boshlang‘ich qoldiqni «Kirim» orqali kiriting.</div></div></section><p class="data-note">Retsept, batch tannarxi va foyda «Retsept va foyda» bo‘limida. Sotuvdan oldin xomashyo qoldig‘ini Kirim orqali kiriting.</p><AppModal :open="!!modal" :title="modal==='item'?'Yangi mahsulot':modal==='receipt'?'Omborga kirim':'Kunlik haqiqiy sarf'" @close="!busy&&(modal='')"><form @submit.prevent="save"><fieldset :disabled="busy||!!pending"><template v-if="modal==='item'"><label>Mahsulot nomi<input v-model="item.name" required maxlength="100"></label><div class="form-row"><label>Birlik<select v-model="item.unit"><option>kg</option><option>l</option><option>dona</option></select></label><label>Minimal qoldiq<input v-model="item.minimum" type="number" min="0" step="0.001" required></label></div></template><template v-else><label>Mahsulot<select v-model="form.ingredient" required><option v-for="i in ingredients" :key="i.id" :value="i.id">{{ i.name }} · {{ money(i.quantity) }} {{ i.unit }}</option></select></label><div class="form-row"><label>Miqdor<input v-model="form.quantity" type="number" min="0.001" step="0.001" required></label><label>Sana<input v-model="form.date" type="date" :min="today()" :max="today()" required></label></div><label>Izoh / sabab<textarea v-model="form.note" required maxlength="250" rows="2"/></label></template></fieldset><p v-if="modal==='consumption'" class="alert">Kiritilgan miqdor ombor qoldig‘idan ayriladi. Bir sarfni qayta kiritmang.</p><p v-if="formError" class="alert error">{{ formError }}</p><button class="button primary full" :disabled="busy">{{ busy?'Saqlanmoqda…':pending?'Oldingi amalni tekshirish':'Hisobga olish' }}</button></form></AppModal></template>
